using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Jellyfin.Plugin.TvHeadendApi.Configuration;

namespace Jellyfin.Plugin.TvHeadendApi.Service.Helper;

/// <summary>
/// Provides centralized access to TVHeadend configuration, URL creation, and HTTP client setup.
/// Creates per-request <see cref="HttpClient"/> instances with Basic authentication
/// headers so TVHeadend accepts the requests without a 401 challenge round-trip.
/// </summary>
internal sealed class ApiClient : IApiClient
{
    /// <summary>
    /// Named HTTP client for standard TVHeadend connections with certificate revocation checks.
    /// </summary>
    internal const string HttpClientName = "TvHeadend";

    /// <summary>
    /// Named HTTP client for TVHeadend connections that skip certificate validation (self-signed certs).
    /// </summary>
    internal const string HttpClientUnsafeName = "TvHeadendUnsafe";

    private readonly IHttpClientFactory _httpClientFactory;
    private readonly PluginConfigurationProvider _configProvider;

    /// <summary>
    /// Initializes a new instance of the <see cref="ApiClient"/> class.
    /// </summary>
    /// <param name="httpClientFactory">The HTTP client factory for creating managed client instances.</param>
    /// <param name="configProvider">Provider for the current plugin configuration.</param>
    public ApiClient(IHttpClientFactory httpClientFactory, PluginConfigurationProvider configProvider)
    {
        ArgumentNullException.ThrowIfNull(httpClientFactory);
        ArgumentNullException.ThrowIfNull(configProvider);
        _httpClientFactory = httpClientFactory;
        _configProvider = configProvider;
    }

    /// <inheritdoc />
    public PluginConfiguration? GetCurrentConfiguration()
    {
        return _configProvider.Configuration;
    }

    /// <inheritdoc />
    public HttpClient BuildHttpClient(PluginConfiguration config)
    {
        ArgumentNullException.ThrowIfNull(config);

        // When credentials are configured, create a dedicated HttpClientHandler with
        // CredentialCache so .NET automatically responds to the server's 401 challenge
        // with the correct auth scheme (Basic, Digest, or both).
        // This bypasses IHttpClientFactory for authenticated requests because the
        // factory-registered handlers cannot accept per-request credentials.
        if (!config.AllowAnonymousAccess && !string.IsNullOrWhiteSpace(config.Username))
        {
            var serverUri = new Uri(UrlHelper.GetBaseUrl(config));
            var credential = new NetworkCredential(config.Username, config.Password);

            var credentialCache = new CredentialCache
            {
                { serverUri, "Basic", credential },
                { serverUri, "Digest", credential },
            };

#pragma warning disable CA5400 // User explicitly opted into ignoring certificate errors via config
            var handler = new HttpClientHandler
            {
                PreAuthenticate = true,
                Credentials = credentialCache,
                CheckCertificateRevocationList = true,
            };

            if (config.UseSSL && config.IgnoreCertificateErrors)
            {
                handler.CheckCertificateRevocationList = false;
                handler.ServerCertificateCustomValidationCallback = static (_, _, _, _) => true;
            }

            var client = new HttpClient(handler);

            // Send a proactive Basic Authorization header so TVHeadend accepts
            // the very first request without requiring a 401 challenge round-trip.
            // The CredentialCache remains as fallback for Digest auth negotiation.
            var basicToken = Convert.ToBase64String(
                Encoding.UTF8.GetBytes($"{config.Username}:{config.Password}"));
            client.DefaultRequestHeaders.Authorization =
                new AuthenticationHeaderValue("Basic", basicToken);

            return client;
#pragma warning restore CA5400
        }

        // Anonymous access — use the factory-managed client (connection pooling, resilience handler).
        var clientName = config.UseSSL && config.IgnoreCertificateErrors
            ? HttpClientUnsafeName
            : HttpClientName;

        return _httpClientFactory.CreateClient(clientName);
    }

    /// <inheritdoc />
    public string GetBaseUrl(PluginConfiguration config)
    {
        return UrlHelper.GetBaseUrl(config);
    }

    /// <inheritdoc />
    public string GetWebRoot(PluginConfiguration config)
    {
        return UrlHelper.GetWebRoot(config);
    }

    /// <inheritdoc />
    public string BuildUrl(PluginConfiguration config, string endpoint)
    {
        return UrlHelper.BuildEndpointUrl(config, endpoint);
    }

    /// <inheritdoc />
    public Task<string> GetStringAsync(HttpClient httpClient, string url, CancellationToken cancellationToken)
    {
        return httpClient.GetStringAsync(url, cancellationToken);
    }

    /// <inheritdoc />
    public Task<HttpResponseMessage> PostFormAsync(
        HttpClient httpClient,
        string url,
        IEnumerable<KeyValuePair<string, string>> formValues,
        CancellationToken cancellationToken)
    {
        var content = new FormUrlEncodedContent(formValues);
        return httpClient.PostAsync(url, content, cancellationToken);
    }

    /// <inheritdoc />
    public async Task<global::System.IO.Stream> GetStreamAsync(HttpClient httpClient, string url, CancellationToken cancellationToken)
    {
        using var response = await httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);
        response.EnsureSuccessStatusCode();

        using var source = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);
        var target = new MemoryStream();
        await source.CopyToAsync(target, cancellationToken).ConfigureAwait(false);
        target.Position = 0;
        return target;
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Jellyfin.Plugin.TvHeadendApi.Configuration;

namespace Jellyfin.Plugin.TvHeadendApi.Service.Helper;

/// <summary>
/// Provides centralized HTTP client creation and request execution for TVHeadend API calls.
/// <para>
/// Anonymous requests use factory-managed clients (connection pooling, resilience).
/// Authenticated requests create an explicit <see cref="HttpClientHandler"/> with
/// <see cref="CredentialCache"/> for Basic+Digest support, wrapped in a
/// <see cref="ResilienceHandler"/> for retry and circuit-breaker behavior.
/// The handler is created intentionally — no casting of factory-internal handlers —
/// so this remains safe under .NET 9 where <c>SocketsHttpHandler</c> is the default.
/// </para>
/// </summary>
internal sealed class ApiClient : IApiClient
{
    /// <summary>
    /// Named HTTP client for standard TVHeadend connections with certificate revocation checks.
    /// </summary>
    internal const string HttpClientName = "TvHeadend";

    /// <summary>
    /// Named HTTP client for TVHeadend connections that skip certificate validation (self-signed certs).
    /// </summary>
    internal const string HttpClientUnsafeName = "TvHeadendUnsafe";

    private readonly IHttpClientFactory _httpClientFactory;
    private readonly PluginConfigurationProvider _configProvider;

    /// <summary>
    /// Initializes a new instance of the <see cref="ApiClient"/> class.
    /// </summary>
    /// <param name="httpClientFactory">The HTTP client factory for creating managed client instances.</param>
    /// <param name="configProvider">Provider for the current plugin configuration.</param>
    public ApiClient(IHttpClientFactory httpClientFactory, PluginConfigurationProvider configProvider)
    {
        ArgumentNullException.ThrowIfNull(httpClientFactory);
        ArgumentNullException.ThrowIfNull(configProvider);
        _httpClientFactory = httpClientFactory;
        _configProvider = configProvider;
    }

    /// <inheritdoc />
    public PluginConfiguration? GetCurrentConfiguration()
    {
        return _configProvider.Configuration;
    }

    /// <inheritdoc />
    public HttpClient CreateApiHttpClient(PluginConfiguration config)
    {
        ArgumentNullException.ThrowIfNull(config);

        // When credentials are configured, create a dedicated HttpClientHandler with
        // CredentialCache so .NET automatically responds to the server's 401 challenge
        // with the correct auth scheme (Basic, Digest, or both).
        // The handler is wrapped in a ResilienceHandler for retry/circuit-breaker parity
        // with factory-managed clients.
        // This bypasses IHttpClientFactory because the factory-registered handlers
        // cannot accept per-request credentials, and casting factory handlers to
        // HttpClientHandler is unsafe in .NET 9 where SocketsHttpHandler is the default.
        if (!config.AllowAnonymousAccess && !string.IsNullOrWhiteSpace(config.Username))
        {
            return CreateAuthenticatedClient(config);
        }

        // Anonymous access — use the factory-managed client (connection pooling, resilience handler).
        var clientName = config.UseSSL && config.IgnoreCertificateErrors
            ? HttpClientUnsafeName
            : HttpClientName;

        return _httpClientFactory.CreateClient(clientName);
    }

    /// <inheritdoc />
    public Task<string> GetStringAsync(HttpClient httpClient, string url, CancellationToken cancellationToken)
    {
        return httpClient.GetStringAsync(url, cancellationToken);
    }

    /// <inheritdoc />
    public Task<HttpResponseMessage> PostFormAsync(
        HttpClient httpClient,
        string url,
        IEnumerable<KeyValuePair<string, string>> formValues,
        CancellationToken cancellationToken)
    {
        var content = new FormUrlEncodedContent(formValues);
        return httpClient.PostAsync(url, content, cancellationToken);
    }

    /// <inheritdoc />
    public async Task<Stream> GetStreamAsync(HttpClient httpClient, string url, CancellationToken cancellationToken)
    {
        using var response = await httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);
        response.EnsureSuccessStatusCode();

        using var source = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);
        var target = new MemoryStream();
        await source.CopyToAsync(target, cancellationToken).ConfigureAwait(false);
        target.Position = 0;
        return target;
    }

    /// <summary>
    /// Creates an authenticated <see cref="HttpClient"/> with proactive Basic header
    /// and CredentialCache fallback for Digest, wrapped in a <see cref="ResilienceHandler"/>.
    /// </summary>
    private static HttpClient CreateAuthenticatedClient(PluginConfiguration config)
    {
        var serverUri = new Uri($"{(config.UseSSL ? "https" : "http")}://{config.Host}:{config.Port}");
        var credential = new NetworkCredential(config.Username, config.Password);

        var credentialCache = new CredentialCache
        {
            { serverUri, "Basic", credential },
            { serverUri, "Digest", credential },
        };

#pragma warning disable CA5400 // User explicitly opted into ignoring certificate errors via config
        var innerHandler = new HttpClientHandler
        {
            PreAuthenticate = true,
            Credentials = credentialCache,
            CheckCertificateRevocationList = true,
        };

        if (config.UseSSL && config.IgnoreCertificateErrors)
        {
            innerHandler.CheckCertificateRevocationList = false;
            innerHandler.ServerCertificateCustomValidationCallback = static (_, _, _, _) => true;
        }
#pragma warning restore CA5400

        // Wrap in ResilienceHandler to get retry + circuit-breaker parity with factory-managed clients.
        var resilienceHandler = new ResilienceHandler { InnerHandler = innerHandler };
        var client = new HttpClient(resilienceHandler);

        // Send a proactive Basic Authorization header so TVHeadend accepts
        // the very first request without requiring a 401 challenge round-trip.
        // The CredentialCache remains as fallback for Digest auth negotiation.
        var basicToken = Convert.ToBase64String(
            Encoding.UTF8.GetBytes($"{config.Username}:{config.Password}"));
        client.DefaultRequestHeaders.Authorization =
            new AuthenticationHeaderValue("Basic", basicToken);

        return client;
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Jellyfin.Plugin.TvHeadendApi.Configuration;
using Jellyfin.Plugin.TvHeadendApi.Service.Helper;
using Moq;
using Xunit;

namespace Jellyfin.Plugin.TvHeadendApi.Tests;

/// <summary>
/// Infrastructure Tests for ApiClient and HTTP operations.
/// Tests the HTTP abstraction layer and basic client operations.
/// </summary>
public class ApiClientTests
{
    private readonly PluginConfiguration _testConfig = new()
    {
        Host = "tvheadend.test.local",
        Port = 9981,
        UseSSL = false,
        Webroot = "/",
        AllowAnonymousAccess = true
    };

    private static IHttpClientFactory CreateMockFactory(HttpMessageHandler? handler = null)
    {
        var mock = new Mock<IHttpClientFactory>();
        mock.Setup(f => f.CreateClient(It.IsAny<string>()))
            .Returns(() => handler != null ? new HttpClient(handler) : new HttpClient());
        return mock.Object;
    }

    private static PluginConfigurationProvider CreateConfigProvider(PluginConfiguration? config = null)
    {
        return new PluginConfigurationProvider(() => config);
    }

    private static ApiClient CreateApiClient(IHttpClientFactory? factory = null, PluginConfigurationProvider? configProvider = null)
    {
        return new ApiClient(factory ?? CreateMockFactory(), configProvider ?? CreateConfigProvider());
    }

    [Fact]
    public void BuildHttpClient_WithValidConfig_ReturnsHttpClient()
    {
        // Arrange
        var client = CreateApiClient();

        // Act
        var result = client.CreateApiHttpClient(_testConfig);

        // Assert
        Assert.NotNull(result);
        Assert.IsType<HttpClient>(result);
    }

    [Fact]
    public void BuildHttpClient_UsesHttpClientFactory()
    {
        // Arrange
        var factoryMock = new Mock<IHttpClientFactory>();
        var expectedClient = new HttpClient();
        factoryMock.Setup(f => f.CreateClient(ApiClient.HttpClientName)).Returns(expectedClient);
        var client = CreateApiClient(factoryMock.Object);

        // Act
        var result = client.CreateApiHttpClient(_testConfig);

        // Assert
        Assert.Same(expectedClient, result);
        factoryMock.Verify(f => f.CreateClient(ApiClient.HttpClientName), Times.Once);
    }

    [Fact]
    public void BuildHttpClient_WithIgnoreCertificateErrors_UsesUnsafeClient()
    {
        // Arrange
        var factoryMock = new Mock<IHttpClientFactory>();
        factoryMock.Setup(f => f.CreateClient(It.IsAny<string>())).Returns(new HttpClient());
        var client = CreateApiClient(factoryMock.Object);
        var config = new PluginConfiguration { UseSSL = true, IgnoreCertificateErrors = true, AllowAnonymousAccess = true };

        // Act
        client.CreateApiHttpClient(config);

        // Assert
        factoryMock.Verify(f => f.CreateClient(ApiClient.HttpClientUnsafeName), Times.Once);
    }

    [Fact]
    public void BuildHttpClient_WithCredentials_DoesNotSetProactiveAuthHeader()
    {
        // Arrange
        var client = CreateApiClient();
        var config = new PluginConfiguration
        {
            AllowAnonymousAccess = false,
            Username = "admin",
            Password = "secret"
        };

        // Act
        var httpClient = client.CreateApiHttpClient(config);

        // Assert — No proactive Authorization header is set because TVHeadend
        // uses Digest auth by default. A proactive Basic header would prevent
        // HttpClientHandler from responding to the Digest challenge.
        Assert.Null(httpClient.DefaultRequestHeaders.Authorization);
    }

    [Fact]
    public void BuildHttpClient_WithCredentials_ReturnsDistinctClientFromFactory()
    {
        // Arrange — verify authenticated path does NOT use factory
        var factoryMock = new Mock<IHttpClientFactory>();
        factoryMock.Setup(f => f.CreateClient(It.IsAny<string>())).Returns(new HttpClient());
        var client = CreateApiClient(factoryMock.Object);
        var config = new PluginConfiguration
        {
            Host = "tvh.local",
            Port = 9981,
            AllowAnonymousAccess = false,
            Username = "admin",
            Password = "secret"
        };

        // Act
        client.CreateApiHttpClient(config);

        // Assert — factory was not called, a dedicated handler was created
        factoryMock.Verify(f => f.CreateClient(It.IsAny<string>()), Times.Never);
    }

    [Fact]
    public void BuildHttpClient_WithCredentials_SetsCorrectBase64Token()
    {
        // Arrange
        var client = CreateApiClient();
        var config = new PluginConfiguration
        {
            Host = "tvh.local",
            Port = 9981,
            AllowAnonymousAccess = false,
            Username = "admin",
            Password = "secret"
        };

        // Act
        var httpClient = client.CreateApiHttpClient(config);

        // Assert — Verify the Base64 token decodes to "admin:secret"
        var auth = httpClient.DefaultRequestHeaders.Authorization;
        Assert.NotNull(auth);
        Assert.Equal("Basic", auth.Scheme);
        var decoded = Encoding.UTF8.GetString(Convert.FromBase64String(auth.Parameter!));
        Assert.Equal("admin:secret", decoded);
    }

    [Fact]
    public async Task BuildHttpClient_WithCredentials_SendsAuthHeaderOnRequest()
    {
        // Arrange — capture the Authorization header that actually arrives at the handler
        string? capturedAuthHeader = null;
        var innerHandler = new MockHttpMessageHandler
        {
            OnRequest = msg =>
            {
                capturedAuthHeader = msg.Headers.Authorization?.ToString();
            },
            Response = new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("{}")
            }
        };

        // Build authenticated client, then replace the handler chain so we can inspect the request.
        // We replicate what CreateAuthenticatedClient does: set the default header on a client
        // that uses our mock handler, to prove the header actually travels with the request.
        var config = new PluginConfiguration
        {
            Host = "tvh.local",
            Port = 9981,
            AllowAnonymousAccess = false,
            Username = "admin",
            Password = "s€cret"  // non-ASCII to test UTF-8 encoding
        };

        var apiClient = CreateApiClient();
        var realHttpClient = apiClient.CreateApiHttpClient(config);
        var expectedAuth = realHttpClient.DefaultRequestHeaders.Authorization;

        // Create a testable client with the same header
        var testClient = new HttpClient(innerHandler);
        testClient.DefaultRequestHeaders.Authorization = expectedAuth;

        // Act — make an actual HTTP call through the mock handler
        var cts = new CancellationTokenSource(TimeSpan.FromSeconds(5));
        await apiClient.GetStringAsync(testClient, "http://tvh.local:9981/api/serverinfo", cts.Token);

        // Assert — the Authorization header was sent with the request
        Assert.NotNull(capturedAuthHeader);
        Assert.StartsWith("Basic ", capturedAuthHeader);

        // Verify the token decodes correctly (including non-ASCII)
        var token = capturedAuthHeader.Substring("Basic ".Length);
        var decoded = Encoding.UTF8.GetString(Convert.FromBase64String(token));
        Assert.Equal("admin:s€cret", decoded);
    }

    [Fact]
    public void BuildHttpClient_WithEmptyUsername_UsesFactoryClient()
    {
        // Arrange — AllowAnonymousAccess=false but username is empty → should fall through to factory
        var factoryMock = new Mock<IHttpClientFactory>();
        factoryMock.Setup(f => f.CreateClient(ApiClient.HttpClientName)).Returns(new HttpClient());
        var client = CreateApiClient(factoryMock.Object);
        var config = new PluginConfiguration
        {
            AllowAnonymousAccess = false,
            Username = "",
            Password = "secret"
        };

        // Act
        var httpClient = client.CreateApiHttpClient(config);

        // Assert — no proactive auth header, factory was used
        Assert.Null(httpClient.DefaultRequestHeaders.Authorization);
        factoryMock.Verify(f => f.CreateClient(ApiClient.HttpClientName), Times.Once);
    }

    [Fact]
    public void GetBaseUrl_WithValidConfig_ReturnsUrl()
    {
        // Arrange
        var urlBuilder = new UrlBuilder();

        // Act
        var url = urlBuilder.GetBaseUrl(_testConfig);

        // Assert
        Assert.NotNull(url);
        Assert.NotEmpty(url);
        Assert.StartsWith("http://", url);
    }

    [Fact]
    public void GetBaseUrl_IncludesHostAndPort()
    {
        // Arrange
        var urlBuilder = new UrlBuilder();

        // Act
        var url = urlBuilder.GetBaseUrl(_testConfig);

        // Assert
        Assert.Contains("tvheadend.test.local", url);
        Assert.Contains("9981", url);
    }

    [Fact]
    public void GetWebRoot_ReturnsNormalizedWebroot()
    {
        // Arrange
        var urlBuilder = new UrlBuilder();

        // Act
        var webroot = urlBuilder.GetWebRoot(_testConfig);

        // Assert
        Assert.NotNull(webroot);
        Assert.NotEmpty(webroot);
    }

    [Fact]
    public void BuildUrl_WithEndpoint_ConstructsFullUrl()
    {
        // Arrange
        var urlBuilder = new UrlBuilder();

        // Act
        var url = urlBuilder.BuildApiUrl(_testConfig, "/api/channel/grid");

        // Assert
        Assert.NotNull(url);
        Assert.Contains("tvheadend.test.local", url);
        Assert.Contains("api/channel/grid", url);
    }

    [Fact]
    public async Task GetStringAsync_WithMockedHttpClient_ReturnsString()
    {
        // Arrange
        var client = CreateApiClient();
        var mockHandler = new MockHttpMessageHandler
        {
            Response = new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("{\"result\":\"success\"}")
            }
        };
        var httpClient = new HttpClient(mockHandler);
        var cts = new CancellationTokenSource();

        // Act
        var result = await client.GetStringAsync(httpClient, "http://localhost:9981/api/test", cts.Token);

        // Assert
        Assert.NotNull(result);
        Assert.Contains("result", result);
    }

    [Fact]
    public async Task GetStringAsync_WithCancellation_ThrowsOperationCanceledException()
    {
        // Arrange
        var client = CreateApiClient();
        var mockHandler = new MockHttpMessageHandler
        {
            Delay = 1000
        };
        var httpClient = new HttpClient(mockHandler);
        var cts = new CancellationTokenSource(100);

        // Act & Assert
        await Assert.ThrowsAnyAsync<OperationCanceledException>(async () =>
            await client.GetStringAsync(httpClient, "http://localhost:9981/api/test", cts.Token)
        );
    }

    [Fact]
    public async Task PostFormAsync_WithValidData_ReturnsHttpResponse()
    {
        // Arrange
        var client = CreateApiClient();
        var mockHandler = new MockHttpMessageHandler
        {
            Response = new HttpResponseMessage(HttpStatusCode.OK)
        };
        var httpClient = new HttpClient(mockHandler);
        var formData = new Dictionary<string, string>
        {
            { "username", "admin" },
            { "password", "secret" }
        };
        var cts = new CancellationTokenSource();

        // Act
        var result = await client.PostFormAsync(httpClient, "http://localhost:9981/api/login", formData, cts.Token);

        // Assert
        Assert.NotNull(result);
        Assert.Equal(HttpStatusCode.OK, result.StatusCode);
    }

    [Fact]
    public async Task PostFormAsync_WithFormContent_IncludesFormData()
    {
        // Arrange
        var client = CreateApiClient();
        var capturedRequest = false;
        var mockHandler = new MockHttpMessageHandler
        {
            OnRequest = msg =>
            {
                if (msg.Content is FormUrlEncodedContent)
                {
                    capturedRequest = true;
                }
            },
            Response = new HttpResponseMessage(HttpStatusCode.OK)
        };
        var httpClient = new HttpClient(mockHandler);
        var formData = new Dictionary<string, string> { { "key", "value" } };
        var cts = new CancellationTokenSource();

        // Act
        await client.PostFormAsync(httpClient, "http://localhost:9981/api/test", formData, cts.Token);

        // Assert
        Assert.True(capturedRequest);
    }

    [Fact]
    public async Task GetStreamAsync_WithValidResponse_ReturnsStream()
    {
        // Arrange
        var client = CreateApiClient();
        var mockHandler = new MockHttpMessageHandler
        {
            Response = new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new ByteArrayContent(new byte[] { 1, 2, 3, 4, 5 })
            }
        };
        var httpClient = new HttpClient(mockHandler);
        var cts = new CancellationTokenSource();

        // Act
        var result = await client.GetStreamAsync(httpClient, "http://localhost:9981/api/stream", cts.Token);

        // Assert
        Assert.NotNull(result);
        Assert.True(result.CanRead);
        Assert.Equal(5, result.Length);
    }

    [Fact]
    public async Task GetStreamAsync_WithFailedResponse_ThrowsHttpRequestException()
    {
        // Arrange
        var client = CreateApiClient();
        var mockHandler = new MockHttpMessageHandler
        {
            Response = new HttpResponseMessage(HttpStatusCode.NotFound)
        };
        var httpClient = new HttpClient(mockHandler);
        var cts = new CancellationTokenSource();

        // Act & Assert
        await Assert.ThrowsAsync<HttpRequestException>(async () =>
            await client.GetStreamAsync(httpClient, "http://localhost:9981/api/notfound", cts.Token)
        );
    }

    [Fact]
    public void BuildUrl_WithDifferentEndpoints_ReturnsDifferentUrls()
    {
        // Arrange
        var urlBuilder = new UrlBuilder();

        // Act
        var url1 = urlBuilder.BuildApiUrl(_testConfig, "/api/channel/grid");
        var url2 = urlBuilder.BuildApiUrl(_testConfig, "/api/dvr/autorec/grid");

        // Assert
        Assert.NotEqual(url1, url2);
        Assert.Contains("channel/grid", url1);
        Assert.Contains("dvr/autorec/grid", url2);
    }

    [Fact]
    public async Task GetStringAsync_MultipleRequests_BothSucceed()
    {
        // Arrange
        var client = CreateApiClient();
        var mockHandler = new MockHttpMessageHandler
        {
            ResponseFactory = () => new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("{\"data\":\"test\"}")
            }
        };
        var httpClient = new HttpClient(mockHandler);
        var cts = new CancellationTokenSource();

        // Act
        var result1 = await client.GetStringAsync(httpClient, "http://localhost:9981/api/1", cts.Token);
        var result2 = await client.GetStringAsync(httpClient, "http://localhost:9981/api/2", cts.Token);

        // Assert
        Assert.NotNull(result1);
        Assert.NotNull(result2);
    }

    /// <summary>
    /// Mock HTTP message handler for testing HTTP operations.
    /// </summary>
    private sealed class MockHttpMessageHandler : HttpMessageHandler
    {
        public HttpResponseMessage? Response { get; set; }
        public Func<HttpResponseMessage>? ResponseFactory { get; set; }
        public Action<HttpRequestMessage>? OnRequest { get; set; }
        public int Delay { get; set; }

        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            OnRequest?.Invoke(request);

            if (Delay > 0)
            {
                await Task.Delay(Delay, cancellationToken).ConfigureAwait(false);
            }

            return ResponseFactory?.Invoke() ?? Response ?? new HttpResponseMessage(HttpStatusCode.OK);
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Jellyfin.Plugin.TvHeadendApi.Configuration;
using Jellyfin.Plugin.TvHeadendApi.Service.Helper;
using Moq;
using Xunit;

namespace Jellyfin.Plugin.TvHeadendApi.Tests;

/// <summary>
/// Infrastructure Tests for ApiClient and HTTP operations.
/// Tests the HTTP abstraction layer and basic client operations.
/// </summary>
public class ApiClientTests
{
    private readonly PluginConfiguration _testConfig = new()
    {
        Host = "tvheadend.test.local",
        Port = 9981,
        UseSSL = false,
        Webroot = "/",
        AllowAnonymousAccess = true
    };

    private static IHttpClientFactory CreateMockFactory(HttpMessageHandler? handler = null)
    {
        var mock = new Mock<IHttpClientFactory>();
        mock.Setup(f => f.CreateClient(It.IsAny<string>()))
            .Returns(() => handler != null ? new HttpClient(handler) : new HttpClient());
        return mock.Object;
    }

    private static PluginConfigurationProvider CreateConfigProvider(PluginConfiguration? config = null)
    {
        return new PluginConfigurationProvider(() => config);
    }

    private static ApiClient CreateApiClient(IHttpClientFactory? factory = null, PluginConfigurationProvider? configProvider = null)
    {
        return new ApiClient(factory ?? CreateMockFactory(), configProvider ?? CreateConfigProvider());
    }

