    {
        var streamResolver = new Mock<IProfileResolver>();
        streamResolver
            .Setup(x => x.GetProfilesAsync(
                It.IsAny<HttpClient>(), It.IsAny<string>(), It.IsAny<string>(), It.IsAny<CancellationToken>()))
