    public async Task<IEnumerable<ChannelInfo>> GetChannelsAsync(CancellationToken cancellationToken)
    {
        try
        {
            var config = GetConfig();
            var url = _tvheadendUrlBuilder.BuildApiUrl(config, "api/channel/grid");
            _logger.LogDebug("Fetching channels from TVHeadEnd at {Url}...", _tvheadendUrlBuilder.MaskSensitiveData(url, config));

            using var httpClient = _tvheadendApiClient.CreateApiHttpClient(config);
            var result = await GridFetcher.FetchAllAsync<ChannelGridResponse>(
                httpClient,
                url,
                r => r.Total,
                _logger,
                cancellationToken).ConfigureAwait(false);
            if (result?.Entries == null || !result.Entries.Any())
            {
                _logger.LogWarning("No channels retrieved from TVHeadEnd.");
                return Enumerable.Empty<ChannelInfo>();
            }

            var channelTagNames = await GetChannelTagsAsync(cancellationToken).ConfigureAwait(false);

            return result.Entries
                .Where(channel => channel.Enabled)
                .Select(channel =>
                {
                    var resolvedTags = (channel.Tags ?? Array.Empty<string>())
                        .Where(tagId => !string.IsNullOrWhiteSpace(tagId))
                        .Select(tagId => channelTagNames.TryGetValue(tagId, out var tagName) && !string.IsNullOrWhiteSpace(tagName)
                            ? tagName
                            : tagId)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .ToArray();

                    var channelGroup = !string.IsNullOrWhiteSpace(channel.Bouquet)
                        ? channel.Bouquet
                        : resolvedTags.FirstOrDefault();

                    return new ChannelInfo
                    {
                        Id = channel.Uuid,
                        Name = channel.Name,
                        Number = FormatChannelNumber(channel.Number),
                        ImageUrl = !string.IsNullOrWhiteSpace(channel.IconPublicUrl)
                            ? _tvheadendUrlBuilder.BuildResourceUrl(config, channel.IconPublicUrl.TrimStart('/'))
                            : null,
                        HasImage = !string.IsNullOrWhiteSpace(channel.IconPublicUrl),
                        Tags = resolvedTags,
                        ChannelGroup = channelGroup,
                    };
                })
                .ToList();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error fetching channels from TVHeadEnd.");
            return Enumerable.Empty<ChannelInfo>();
        }
    }

    public async Task<IEnumerable<ProgramInfo>> GetProgramsAsync(string channelId, DateTime startDateUtc, DateTime endDateUtc, CancellationToken cancellationToken)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(channelId);

        try
        {
            var config = GetConfig();
            var encodedChannelId = Uri.EscapeDataString(channelId);

            // Pass server-side time-window filter to TVHeadend to reduce payload size.
            // TVH filter: stop > startDateUtc AND start < endDateUtc (overlap condition).
            var startUnix = new DateTimeOffset(startDateUtc, TimeSpan.Zero).ToUnixTimeSeconds();
            var endUnix = new DateTimeOffset(endDateUtc, TimeSpan.Zero).ToUnixTimeSeconds();
            var filterJson = "[{\"field\":\"stop\",\"type\":\"numeric\",\"value\":" + startUnix
                + ",\"comparison\":\"gt\"},{\"field\":\"start\",\"type\":\"numeric\",\"value\":" + endUnix
                + ",\"comparison\":\"lt\"}]";
            var encodedFilter = Uri.EscapeDataString(filterJson);
            var url = _tvheadendUrlBuilder.BuildApiUrl(config, $"api/epg/events/grid?channel={encodedChannelId}&filter={encodedFilter}");
            using var httpClient = _tvheadendApiClient.CreateApiHttpClient(config);
            var result = await GridFetcher.FetchAllAsync<EpgEventsGridResponse>(
                httpClient,
                url,
                r => r.TotalCount,
                _logger,
                cancellationToken).ConfigureAwait(false);
            return result?.Entries?
                .Where(entry =>
                {
                    var programStart = DateTimeOffset.FromUnixTimeSeconds(entry.Start).UtcDateTime;
                    var programEnd = DateTimeOffset.FromUnixTimeSeconds(entry.Stop).UtcDateTime;
                    return entry.ChannelUuid == channelId && programStart < endDateUtc && programEnd > startDateUtc;
                })
                .Select(entry =>
                {
                    string? imageUrl = null;
                    if (!string.IsNullOrWhiteSpace(entry.Image))
                    {
                        imageUrl = ResolveTvhImageUrl(config, entry.Image);
                    }
                    else if (!string.IsNullOrWhiteSpace(entry.ChannelIcon))
                    {
                        imageUrl = ResolveTvhImageUrl(config, entry.ChannelIcon);
                    }

                    var ratingLabelIconUrl = string.IsNullOrWhiteSpace(entry.RatingLabelIcon)
                        ? null
                        : ResolveTvhImageUrl(config, entry.RatingLabelIcon);

                    var providerHints = config.EnableJellyfinMetadataEnrichment
                        ? BuildProviderHints(entry)
                        : null;

                    var categories = entry.Category ?? Array.Empty<string>();
                    var isPremiere = HasCategoryFlag(categories, "premiere", "first run", "new");
                    var isLive = HasCategoryFlag(categories, "live");
                    var isRepeat = !isPremiere && (entry.IsNew == 0 || HasCategoryFlag(categories, "repeat", "rerun", "wiederholung"));

                    DateTime? originalAirDate = null;
                    if (entry.FirstAired.HasValue && entry.FirstAired.Value > 0)
                    {
                        originalAirDate = DateTimeOffset.FromUnixTimeSeconds(entry.FirstAired.Value).UtcDateTime;
                    }

                    return new ProgramInfo
                    {
                        Id = entry.EventId.ToString(CultureInfo.InvariantCulture),
                        ChannelId = entry.ChannelUuid,
                        Name = entry.Title,
                        Overview = entry.Description,
                        ShortOverview = entry.Summary,
                        StartDate = DateTimeOffset.FromUnixTimeSeconds(entry.Start).UtcDateTime,
                        EndDate = DateTimeOffset.FromUnixTimeSeconds(entry.Stop).UtcDateTime,
                        Genres = entry.Genre?.Select(genreId => EtsiGenreMapping.TryGetValue(genreId, out var genreDescription) ? genreDescription : $"Unknown ({genreId})").ToList() ?? new List<string>(),
                        IsHD = entry.IsHD == 1,
                        EpisodeTitle = entry.Subtitle,
                        OfficialRating = entry.RatingLabel,
                        ImageUrl = imageUrl,
                        LogoImageUrl = ratingLabelIconUrl,
                        HasImage = !string.IsNullOrEmpty(imageUrl),
                        IsMovie = entry.Genre?.Any(genreId => genreId >= 16 && genreId <= 24) ?? false,
                        IsSports = entry.Genre?.Any(genreId => genreId >= 64 && genreId <= 75) ?? false,
                        IsNews = entry.Genre?.Any(genreId => genreId >= 32 && genreId <= 36) ?? false,
                        IsKids = entry.Genre?.Any(genreId => genreId >= 80 && genreId <= 83) ?? false,
                        IsEducational = entry.Genre?.Any(genreId => genreId >= 144 && genreId <= 150) ?? false,
                        IsLive = isLive,
                        IsPremiere = isPremiere,
                        IsRepeat = isRepeat,
                        OriginalAirDate = originalAirDate,
                        Audio = MapProgramAudio(entry.Stereo),
                        // IsSeries: prefer SerieslinkUri presence (definitive), fall back to genre 48-51 (Show/Game Show)
                        IsSeries = !string.IsNullOrWhiteSpace(entry.SerieslinkUri)
                            || (entry.Genre?.Any(genreId => genreId >= 48 && genreId <= 51) ?? false),
                        // SeriesId: use SerieslinkUri as a stable identifier for series-timer linking
                        SeriesId = string.IsNullOrWhiteSpace(entry.SerieslinkUri) ? null : entry.SerieslinkUri,
                        ShowId = string.IsNullOrWhiteSpace(entry.SerieslinkUri) ? null : entry.SerieslinkUri,
                        HomePageUrl = Uri.TryCreate(entry.EpisodeUri, UriKind.Absolute, out var episodeUri) ? episodeUri.ToString() : null,
                        ProviderIds = providerHints?.ProviderIds ?? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase),
                        SeriesProviderIds = providerHints?.SeriesProviderIds ?? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase),
                        // ProductionYear from TVH copyright_year (0 = unknown)
                        ProductionYear = entry.CopyrightYear > 0 ? entry.CopyrightYear : null,
                    };
                })
                .ToList() ?? Enumerable.Empty<ProgramInfo>();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error occurred while fetching EPG data for channel ID: {ChannelId}.", channelId);
            return Enumerable.Empty<ProgramInfo>();
        }
    }

    public async Task<Dictionary<int, string>> GetContentTypesAsync(CancellationToken cancellationToken)
    {
        try
        {
            var config = GetConfig();
            var url = _tvheadendUrlBuilder.BuildApiUrl(config, "api/epg/content_type/list");
            using var httpClient = _tvheadendApiClient.CreateApiHttpClient(config);
            using var response = await httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
            {
                return new Dictionary<int, string>();
            }

            using var stream = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);
            var result = await JsonSerializer.DeserializeAsync<EpgContentTypeListResponse>(stream, JsonDefaults.Api, cancellationToken).ConfigureAwait(false);
            return result?.Entries?.ToDictionary(entry => entry.Key, entry => entry.Val) ?? new Dictionary<int, string>();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error occurred while fetching content types from TVHeadend.");
            return new Dictionary<int, string>();
        }
    }

    public async Task<Dictionary<string, string>> GetChannelTagsAsync(CancellationToken cancellationToken)
    {
        try
        {
            var config = GetConfig();
            var url = _tvheadendUrlBuilder.BuildApiUrl(config, "api/channeltag/list");
            using var httpClient = _tvheadendApiClient.CreateApiHttpClient(config);
            using var response = await httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
            {
                return new Dictionary<string, string>();
            }

            using var stream = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);
            var result = await JsonSerializer.DeserializeAsync<ChannelTagResponse>(stream, JsonDefaults.Api, cancellationToken).ConfigureAwait(false);
            return result?.Entries?.ToDictionary(entry => entry.Key, entry => entry.Val) ?? new Dictionary<string, string>();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error occurred while fetching channel tags from TVHeadend.");
            return new Dictionary<string, string>();
        }
    }

    private PluginConfiguration GetConfig()
    {
        return _tvheadendApiClient.GetCurrentConfiguration()
            ?? throw new InvalidOperationException("Plugin configuration is not available.");
    }

    /// <summary>
    /// Formats the TVHeadend channel number for Jellyfin.
    /// <para>
    /// TVHeadend serializes channel numbers in two ways:
    /// <list type="bullet">
    ///   <item>Whole numbers → JSON integer (e.g. <c>10</c>)</item>
    ///   <item>Major.minor → JSON string (e.g. <c>"7.1"</c>)</item>
    /// </list>
    /// Both are passed through as-is since TVHeadend already formats them correctly.
    /// </para>
    /// </summary>
    /// <param name="numberElement">The raw JSON element from the TVHeadend channel grid <c>number</c> field.</param>
    /// <returns>The formatted channel number string (e.g. <c>"10"</c> or <c>"7.1"</c>), or <c>"0"</c> if unavailable.</returns>
    internal static string FormatChannelNumber(JsonElement numberElement)
    {
        if (numberElement.ValueKind == JsonValueKind.Number)
        {
            return numberElement.GetInt64().ToString(CultureInfo.InvariantCulture);
        }

        if (numberElement.ValueKind == JsonValueKind.String)
        {
            var str = numberElement.GetString();
            return !string.IsNullOrWhiteSpace(str) ? str : "0";
        }

        return "0";
    }

    private string ResolveTvhImageUrl(PluginConfiguration config, string rawImagePath)
    {
        var raw = rawImagePath.Trim();
        var normalized = raw.TrimStart('/');

        if (normalized.StartsWith("imagecache/", StringComparison.OrdinalIgnoreCase))
        {
            return _tvheadendUrlBuilder.BuildResourceUrl(config, normalized);
        }

        if (Uri.TryCreate(raw, UriKind.Absolute, out _))
        {
            return raw;
        }

        return _tvheadendUrlBuilder.BuildResourceUrl(config, normalized);
    }

    private static ProviderHintSet BuildProviderHints(EpgEventsGridEntry entry)
    {
        var providerIds = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var seriesProviderIds = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        TryAddKnownProviderIds(providerIds, entry.EpisodeUri);
        TryAddKnownProviderIds(seriesProviderIds, entry.SerieslinkUri);

        return new ProviderHintSet(providerIds, seriesProviderIds);
    }

    private static void TryAddKnownProviderIds(Dictionary<string, string> target, string? source)
    {
        if (string.IsNullOrWhiteSpace(source))
        {
            return;
        }

        var text = source.Trim();

        // IMDb ID (tt1234567+)
        var imdbIdx = text.IndexOf("tt", StringComparison.OrdinalIgnoreCase);
        if (imdbIdx >= 0)
        {
            var end = imdbIdx + 2;
            while (end < text.Length && char.IsDigit(text[end]))
            {
                end++;
            }

            var candidate = text.Substring(imdbIdx, end - imdbIdx);
            if (candidate.Length >= 9)
            {
                target["Imdb"] = candidate;
            }
        }

        // TMDb hints: tmdb://movie/123 or tmdb://tv/123
        const string tmdbMoviePrefix = "tmdb://movie/";
        const string tmdbTvPrefix = "tmdb://tv/";
        if (text.StartsWith(tmdbMoviePrefix, StringComparison.OrdinalIgnoreCase)
            || text.StartsWith(tmdbTvPrefix, StringComparison.OrdinalIgnoreCase))
        {
            var idPart = text.Substring(text.LastIndexOf('/') + 1);
            if (idPart.All(char.IsDigit))
            {
                target["Tmdb"] = idPart;
            }
        }

        // TVDb hints: tvdb://series/123 or thetvdb.com/.../123
        const string tvdbPrefix = "tvdb://";
        if (text.StartsWith(tvdbPrefix, StringComparison.OrdinalIgnoreCase))
        {
            var idPart = text.Substring(text.LastIndexOf('/') + 1);
            if (idPart.All(char.IsDigit))
            {
                target["Tvdb"] = idPart;
            }
        }
    }

    private static ProgramAudio? MapProgramAudio(int? stereoMode)
    {
        return stereoMode switch
        {
            1 => ProgramAudio.Mono,
            2 or 3 => ProgramAudio.Stereo,
            >= 4 => ProgramAudio.DolbyDigital,
            _ => null,
        };
    }

    private static bool HasCategoryFlag(IEnumerable<string> categories, params string[] patterns)
    {
        foreach (var category in categories)
        {
            if (string.IsNullOrWhiteSpace(category))
            {
                continue;
            }

            var normalized = category.Trim();
            foreach (var pattern in patterns)
            {
                if (normalized.Contains(pattern, StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private sealed record ProviderHintSet(
        Dictionary<string, string> ProviderIds,
        Dictionary<string, string> SeriesProviderIds);
}

using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Jellyfin.Plugin.TvHeadendApi.Configuration;

namespace Jellyfin.Plugin.TvHeadendApi.Service.Helper;

/// <summary>
/// Defines a minimal TVHeadend API client abstraction for configuration, URL building, and HTTP client creation.
/// </summary>
public interface IApiClient
{
    /// <summary>
    /// Gets the current plugin configuration if available.
    /// </summary>
    /// <returns>The current plugin configuration, or <see langword="null"/> if the plugin instance is unavailable.</returns>
    PluginConfiguration? GetCurrentConfiguration();

    /// <summary>
    /// Builds a configured HTTP client for TVHeadend API calls.
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <returns>A configured HTTP client instance.</returns>
    HttpClient BuildHttpClient(PluginConfiguration config);

    /// <summary>
    /// Gets the normalized TVHeadend base URL.
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <returns>The normalized TVHeadend base URL.</returns>
    string GetBaseUrl(PluginConfiguration config);

    /// <summary>
    /// Gets the normalized TVHeadend web root.
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <returns>The normalized TVHeadend web root.</returns>
    string GetWebRoot(PluginConfiguration config);

    /// <summary>
    /// Builds a full TVHeadend endpoint URL.
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <param name="endpoint">Relative TVHeadend endpoint.</param>
    /// <returns>The full endpoint URL.</returns>
    string BuildUrl(PluginConfiguration config, string endpoint);

    /// <summary>
    /// Executes a GET request and returns the response body as a string.
    /// </summary>
    /// <param name="httpClient">Configured HTTP client.</param>
    /// <param name="url">Absolute request URL.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>Response body as a string.</returns>
    Task<string> GetStringAsync(HttpClient httpClient, string url, CancellationToken cancellationToken);

    /// <summary>
    /// Executes a GET request and returns the response stream.
    /// </summary>
    /// <param name="httpClient">Configured HTTP client.</param>
    /// <param name="url">Absolute request URL.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>Response stream.</returns>
    Task<global::System.IO.Stream> GetStreamAsync(HttpClient httpClient, string url, CancellationToken cancellationToken);

    /// <summary>
    /// Executes a form POST request and returns the raw HTTP response.
    /// </summary>
    /// <param name="httpClient">Configured HTTP client.</param>
    /// <param name="url">Absolute request URL.</param>
    /// <param name="formValues">Form values to send.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>The raw HTTP response message.</returns>
    Task<HttpResponseMessage> PostFormAsync(
        HttpClient httpClient,
        string url,
        IEnumerable<KeyValuePair<string, string>> formValues,
        CancellationToken cancellationToken);
}

using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Jellyfin.Plugin.TvHeadendApi.Configuration;

namespace Jellyfin.Plugin.TvHeadendApi.Service.Helper;

/// <summary>
/// Provides HTTP client creation and request execution for TVHeadend API calls.
/// URL construction is handled by <see cref="IUrlBuilder"/>; this interface
/// is responsible only for authentication-aware HTTP client lifecycle and
/// raw HTTP operations (GET string, GET stream, POST form).
/// </summary>
public interface IApiClient
{
    /// <summary>
    /// Gets the current plugin configuration if available.
    /// </summary>
    /// <returns>The current plugin configuration, or <see langword="null"/> if the plugin instance is unavailable.</returns>
    PluginConfiguration? GetCurrentConfiguration();

    /// <summary>
    /// Creates an HTTP client configured for TVHeadend API requests.
    /// <para>
    /// When <see cref="PluginConfiguration.AllowAnonymousAccess"/> is <c>false</c> and
    /// credentials are configured, the returned client includes a proactive Basic
    /// Authorization header and a <see cref="System.Net.CredentialCache"/> fallback
    /// for Digest auth negotiation. The handler is created explicitly (not cast from
    /// factory internals) to remain safe under .NET 9.
    /// </para>
    /// <para>
    /// When anonymous access is enabled, the client is obtained from
    /// <see cref="IHttpClientFactory"/> with connection pooling and resilience.
    /// </para>
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <returns>A configured HTTP client instance.</returns>
    HttpClient CreateApiHttpClient(PluginConfiguration config);

    /// <summary>
    /// Executes a GET request and returns the response body as a string.
    /// </summary>
    /// <param name="httpClient">Configured HTTP client.</param>
    /// <param name="url">Absolute request URL.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>Response body as a string.</returns>
    Task<string> GetStringAsync(HttpClient httpClient, string url, CancellationToken cancellationToken);

    /// <summary>
    /// Executes a GET request and returns the response as an in-memory stream.
    /// </summary>
    /// <param name="httpClient">Configured HTTP client.</param>
    /// <param name="url">Absolute request URL.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>Response stream (caller owns the stream).</returns>
    Task<Stream> GetStreamAsync(HttpClient httpClient, string url, CancellationToken cancellationToken);

    /// <summary>
    /// Executes a form POST request and returns the raw HTTP response.
    /// </summary>
    /// <param name="httpClient">Configured HTTP client.</param>
    /// <param name="url">Absolute request URL.</param>
    /// <param name="formValues">Form values to send.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>The raw HTTP response message.</returns>
    Task<HttpResponseMessage> PostFormAsync(
        HttpClient httpClient,
        string url,
        IEnumerable<KeyValuePair<string, string>> formValues,
        CancellationToken cancellationToken);
}

using Jellyfin.Plugin.TvHeadendApi.Configuration;

namespace Jellyfin.Plugin.TvHeadendApi.Service.Helper;

/// <summary>
/// Builds TVHeadend URLs and masks sensitive values for logging.
/// </summary>
internal interface IUrlBuilder
{
    /// <summary>
    /// Builds a plain endpoint URL without any authentication data.
    /// Authentication is handled by <see cref="IApiClient.BuildHttpClient"/> via <see cref="System.Net.NetworkCredential"/>.
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <param name="endpoint">Relative endpoint.</param>
    /// <returns>Absolute URL without credentials.</returns>
    string BuildUrl(PluginConfiguration config, string endpoint);

    /// <summary>
    /// Builds a URL with the auth token appended as a query parameter.
    /// Used for streaming and icon URLs consumed by external clients.
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <param name="endpoint">Relative endpoint.</param>
    /// <returns>Absolute URL with auth token as query parameter.</returns>
    string BuildUrlWithParameterAuth(PluginConfiguration config, string endpoint);

    /// <summary>
    /// Masks auth token and credentials in a string before logging.
    /// </summary>
    /// <param name="input">Input text.</param>
    /// <param name="config">Plugin configuration.</param>
    /// <returns>Masked text.</returns>
    string MaskSensitiveData(string input, PluginConfiguration config);
}

using Jellyfin.Plugin.TvHeadendApi.Configuration;

namespace Jellyfin.Plugin.TvHeadendApi.Service.Helper;

/// <summary>
/// Builds TVHeadend URLs and masks sensitive values for logging.
/// Centralizes all URL construction: base URLs, API endpoint URLs, and
/// token-authenticated resource URLs (streams, icons).
/// </summary>
internal interface IUrlBuilder
{
    /// <summary>
    /// Gets the normalized TVHeadend base URL (scheme + host + port).
    /// Example: <c>https://tvh.local:9981</c>.
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <returns>The base URL without trailing slash.</returns>
    string GetBaseUrl(PluginConfiguration config);

    /// <summary>
    /// Gets the normalized TVHeadend web root path.
    /// Always starts and ends with <c>/</c>.
    /// Example: <c>/tvh/</c> or <c>/</c>.
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <returns>The normalized web root.</returns>
    string GetWebRoot(PluginConfiguration config);

    /// <summary>
    /// Builds a plain API endpoint URL without any authentication data.
    /// Used for standard TVHeadend API requests where authentication is
    /// handled via HTTP headers on the <see cref="System.Net.Http.HttpClient"/>.
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <param name="endpoint">Relative endpoint (e.g. <c>api/channel/grid</c>).</param>
    /// <returns>Absolute URL without credentials.</returns>
    string BuildApiUrl(PluginConfiguration config, string endpoint);

    /// <summary>
    /// Builds a resource URL with the auth token appended as <c>?auth=...</c> query parameter.
    /// Used for streaming endpoints, channel icons, and image URLs that are consumed
    /// by external clients (players, browsers) which cannot attach HTTP auth headers.
    /// <para>
    /// When anonymous access is enabled or no auth token is configured, the URL is
    /// returned without the <c>auth</c> parameter.
    /// </para>
    /// </summary>
    /// <param name="config">Plugin configuration.</param>
    /// <param name="endpoint">Relative endpoint (e.g. <c>stream/channel/123</c>).</param>
    /// <returns>Absolute URL with auth token as query parameter when applicable.</returns>
    string BuildResourceUrl(PluginConfiguration config, string endpoint);

    /// <summary>
    /// Masks auth token, username, and password in a string before logging.
    /// All sensitive values present in <paramref name="config"/> are replaced with <c>***</c>.
    /// </summary>
    /// <param name="input">Input text (typically a URL or response excerpt).</param>
    /// <param name="config">Plugin configuration providing the sensitive values.</param>
    /// <returns>Masked text safe for logging.</returns>
    string MaskSensitiveData(string input, PluginConfiguration config);
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
using Jellyfin.Plugin.TvHeadendApi.Configuration;
using Jellyfin.Plugin.TvHeadendApi.Model;
using MediaBrowser.Controller.LiveTv;
using MediaBrowser.Model.Dto;
using MediaBrowser.Model.Entities;
using MediaBrowser.Model.LiveTv;
using MediaBrowser.Model.MediaInfo;
using Microsoft.Extensions.Logging;

namespace Jellyfin.Plugin.TvHeadendApi.Service;

/// <summary>
/// Provides Live TV integration for Jellyfin using TVHeadEnd as the backend.
/// Implements the <see cref="ILiveTvService"/> interface to manage channels, EPG data, recordings, and streams.
/// </summary>
public sealed class LiveTvService : ILiveTvService, IDisposable
{
    private readonly ILogger<LiveTvService> _logger;
    private readonly object _httpClientSync = new();
    private HttpClient _httpClient;
    private string? _httpClientConfigurationKey;
    private bool _disposed;
    private static readonly JsonSerializerOptions JsonOptions = new JsonSerializerOptions
    {
        PropertyNameCaseInsensitive = true
    };

    /// <summary>
    /// Time-to-live for cached profile details. After this period the plugin re-queries TVHeadend.
    /// </summary>
    private static readonly TimeSpan ProfileDetailsCacheTtl = TimeSpan.FromMinutes(5);

    /// <summary>
    /// Lock to prevent concurrent profile container lookups.
    /// </summary>
    private readonly SemaphoreSlim _profileContainerLock = new(1, 1);

    /// <summary>
    /// Cached profile details (container, codecs, bitrates) derived from the configured
    /// TVHeadend streaming profile. Invalidated when the profile name changes or when the TTL expires.
    /// </summary>
    private ProfileCacheEntry? _profileDetailsCache;

    /// <summary>
    /// JSON options for deserializing Jellyfin's mediainfo cache files.
    /// Uses <see cref="JsonStringEnumConverter"/> because Jellyfin serialises enums as strings
    /// (e.g. <c>"Type": "Video"</c> for <see cref="MediaStreamType"/>).
    /// </summary>
    private static readonly JsonSerializerOptions MediaInfoCacheJsonOptions = new()
    {
