        var result = JsonSerializer.Deserialize<ServerInfoResponse>(json, JsonDefaults.Api);

        Assert.NotNull(result);
        Assert.Equal("4.2", result.SwVersion);
        Assert.Null(result.ApiVersion);
    }

    // ── /api/profile/list ────────────────────────────────────────────

    [Fact]
    public void ProfileList_DeserializesRealisticPayload()
    {
        const string json = """
        {
          "entries": [
            { "key": "abc-uuid-1", "val": "pass" },
            { "key": "def-uuid-2", "val": "jellyfin" },
            { "key": "ghi-uuid-3", "val": "webtv-h264-aac-mpegts" }
          ]
        }
        """;

        var result = JsonSerializer.Deserialize<ProfileListResponse>(json, JsonDefaults.Api);

        Assert.NotNull(result);
        Assert.Equal(3, result.Entries.Length);
        Assert.Equal("pass", result.Entries[0].Val);
        Assert.Equal("jellyfin", result.Entries[1].Val);
        Assert.Equal("def-uuid-2", result.Entries[1].Key);
    }

    // ── /api/epg/content_type/list ───────────────────────────────────

    [Fact]
    public void EpgContentTypeList_DeserializesRealisticPayload()
    {
        const string json = """
        {
          "entries": [
            { "key": 16, "val": "Movie / Drama" },
            { "key": 32, "val": "News / Current affairs" },
            { "key": 64, "val": "Sports" }
          ]
        }
        """;

        var result = JsonSerializer.Deserialize<EpgContentTypeListResponse>(json, JsonDefaults.Api);

        Assert.NotNull(result);
        Assert.Equal(3, result.Entries.Count);
        Assert.Equal(16, result.Entries[0].Key);
        Assert.Equal("Movie / Drama", result.Entries[0].Val);
    }

    // ── Resilience: unknown fields are ignored ───────────────────────

    [Fact]
    public void Deserialization_IgnoresUnknownFields()
    {
        const string json = """
        {
          "entries": [
            {
              "uuid": "abc",
              "name": "Test",
              "number": 1000000,
              "enabled": true,
              "unknown_future_field": "should be ignored",
              "another_new_array": [1, 2, 3]
            }
          ],
          "total": 1,
          "some_new_metadata": true
        }
        """;

        var result = JsonSerializer.Deserialize<ChannelGridResponse>(json, JsonDefaults.Api);

        Assert.NotNull(result);
        Assert.Single(result.Entries);
        Assert.Equal("abc", result.Entries[0].Uuid);
    }

    // ── DVR config grid ──────────────────────────────────────────────

    [Fact]
    public void DvrConfigGrid_DeserializesRealisticPayload()
    {
        const string json = """
        {
          "entries": [
            {
              "uuid": "7a5edfbe189851e5b1d1df19c93962f0",
              "name": "",
              "enabled": true
            }
          ],
          "total": 1
        }
        """;

        var result = JsonSerializer.Deserialize<DvrConfigGridResponse>(json, JsonDefaults.Api);

        Assert.NotNull(result);
        Assert.Single(result.Entries);
        Assert.Equal("7a5edfbe189851e5b1d1df19c93962f0", result.Entries[0].Uuid);
    }
}

using System;
using System.Text;
using Jellyfin.Plugin.TvHeadendApi.Configuration;

namespace Jellyfin.Plugin.TvHeadendApi.Service.Helper;

/// <summary>
/// Default implementation for TVHeadend URL/auth handling.
/// </summary>
internal sealed class UrlBuilder : IUrlBuilder
{
    /// <inheritdoc />
    public string BuildUrlWithHeaderAuth(PluginConfiguration config, string endpoint)
    {
        ArgumentNullException.ThrowIfNull(config);
        ArgumentException.ThrowIfNullOrWhiteSpace(endpoint);

        // Credentials are sent via HTTP header � no auth data embedded in the URL.
        return UrlHelper.BuildEndpointUrl(config, endpoint);
    }

    /// <inheritdoc />
    public string BuildUrlWithUrlAuth(PluginConfiguration config, string endpoint)
    {
        ArgumentNullException.ThrowIfNull(config);
        ArgumentException.ThrowIfNullOrWhiteSpace(endpoint);

        var baseUrl = UrlHelper.BuildEndpointUrl(config, endpoint);
        if (config.AllowAnonymousAccess)
        {
            return baseUrl;
        }

        var credentials = $"{Uri.EscapeDataString(config.Username)}:{Uri.EscapeDataString(config.Password)}";
        return baseUrl
            .Replace("http://", $"http://{credentials}@", StringComparison.Ordinal)
            .Replace("https://", $"https://{credentials}@", StringComparison.Ordinal);
    }

    /// <inheritdoc />
    public string BuildUrlWithParameterAuth(PluginConfiguration config, string endpoint)
    {
        ArgumentNullException.ThrowIfNull(config);
        ArgumentException.ThrowIfNullOrWhiteSpace(endpoint);

        var baseUrl = UrlHelper.BuildEndpointUrl(config, endpoint);
        if (config.AllowAnonymousAccess || string.IsNullOrWhiteSpace(config.AuthToken))
        {
            return baseUrl;
        }

        var separator = baseUrl.Contains('?', StringComparison.Ordinal) ? '&' : '?';
        return $"{baseUrl}{separator}auth={Uri.EscapeDataString(config.AuthToken)}";
    }

    /// <inheritdoc />
    public string MaskSensitiveData(string input, PluginConfiguration config)
    {
        ArgumentNullException.ThrowIfNull(config);

        var output = input;
        if (!string.IsNullOrWhiteSpace(config.AuthToken))
        {
            output = output.Replace(config.AuthToken, "***", StringComparison.Ordinal);
        }

        if (!string.IsNullOrWhiteSpace(config.Username) && !string.IsNullOrWhiteSpace(config.Password))
        {
            var credentials = $"{config.Username}:{config.Password}";
            var encodedCredentials = Convert.ToBase64String(Encoding.UTF8.GetBytes(credentials));
            var urlEncodedCredentials = $"{Uri.EscapeDataString(config.Username)}:{Uri.EscapeDataString(config.Password)}";
            output = output.Replace(credentials, "***", StringComparison.Ordinal);
            output = output.Replace(encodedCredentials, "***", StringComparison.Ordinal);
            output = output.Replace(urlEncodedCredentials, "***", StringComparison.Ordinal);
        }

        return output;
    }
}

using System;
using System.Text;
using Jellyfin.Plugin.TvHeadendApi.Configuration;

namespace Jellyfin.Plugin.TvHeadendApi.Service.Helper;

/// <summary>
/// Default implementation for TVHeadend URL/auth handling.
/// </summary>
internal sealed class UrlBuilder : IUrlBuilder
{
    /// <inheritdoc />
    public string BuildUrlWithHeaderAuth(PluginConfiguration config, string endpoint)
    {
        // TVHeadend does not reliably support HTTP Basic Auth headers in all configurations.
        // Delegate to URL-embedded credentials for consistent authentication.
        return BuildUrlWithUrlAuth(config, endpoint);
    }

    /// <inheritdoc />
    public string BuildUrlWithUrlAuth(PluginConfiguration config, string endpoint)
    {
        ArgumentNullException.ThrowIfNull(config);
        ArgumentException.ThrowIfNullOrWhiteSpace(endpoint);

        var baseUrl = UrlHelper.BuildEndpointUrl(config, endpoint);
        if (config.AllowAnonymousAccess)
        {
            return baseUrl;
        }

        var credentials = $"{Uri.EscapeDataString(config.Username)}:{Uri.EscapeDataString(config.Password)}";
        return baseUrl
            .Replace("http://", $"http://{credentials}@", StringComparison.Ordinal)
            .Replace("https://", $"https://{credentials}@", StringComparison.Ordinal);
    }

    /// <inheritdoc />
    public string BuildUrlWithParameterAuth(PluginConfiguration config, string endpoint)
    {
        ArgumentNullException.ThrowIfNull(config);
        ArgumentException.ThrowIfNullOrWhiteSpace(endpoint);

        var baseUrl = UrlHelper.BuildEndpointUrl(config, endpoint);
        if (config.AllowAnonymousAccess || string.IsNullOrWhiteSpace(config.AuthToken))
        {
            return baseUrl;
        }

        var separator = baseUrl.Contains('?', StringComparison.Ordinal) ? '&' : '?';
        return $"{baseUrl}{separator}auth={Uri.EscapeDataString(config.AuthToken)}";
    }

    /// <inheritdoc />
    public string MaskSensitiveData(string input, PluginConfiguration config)
    {
        ArgumentNullException.ThrowIfNull(config);

        var output = input;
        if (!string.IsNullOrWhiteSpace(config.AuthToken))
        {
            output = output.Replace(config.AuthToken, "***", StringComparison.Ordinal);
        }

        if (!string.IsNullOrWhiteSpace(config.Username) && !string.IsNullOrWhiteSpace(config.Password))
        {
            var credentials = $"{config.Username}:{config.Password}";
            var encodedCredentials = Convert.ToBase64String(Encoding.UTF8.GetBytes(credentials));
            var urlEncodedCredentials = $"{Uri.EscapeDataString(config.Username)}:{Uri.EscapeDataString(config.Password)}";
            output = output.Replace(credentials, "***", StringComparison.Ordinal);
            output = output.Replace(encodedCredentials, "***", StringComparison.Ordinal);
            output = output.Replace(urlEncodedCredentials, "***", StringComparison.Ordinal);
        }

        return output;
    }
}

param(
    [string]$ComposeService = "jellyfin",
    [string]$ComposeFile = "docker\docker-compose.yaml",
    [string]$VersionFile = ".\.dev-volumes\dev-version.txt",
    [switch]$DryRun,
    [switch]$NoLogs
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Step {
    param([string]$Message)
    Write-Host "==> $Message" -ForegroundColor Cyan
}

function Get-VersionFromDockerfile {
    param([string]$DockerfilePath)

    if (-not (Test-Path $DockerfilePath)) {
        throw "Dockerfile not found: $DockerfilePath"
    }

    $line = Get-Content -Path $DockerfilePath | Where-Object { $_ -match '^ARG\s+VERSION=' } | Select-Object -First 1
    if (-not $line) {
        throw "Could not find 'ARG VERSION=...' in Dockerfile."
    }

    return ($line -replace '^ARG\s+VERSION=', '').Trim()
}

function Increment-Version {
    param([string]$VersionText)

    $parts = $VersionText.Split('.')
    if ($parts.Count -ne 4) {
        throw "Version must be in format major.minor.patch.revision, got '$VersionText'."
    }

    $major = [int]$parts[0]
    $minor = [int]$parts[1]
    $patch = [int]$parts[2]
    $rev = [int]$parts[3] + 1

    return "$major.$minor.$patch.$rev"
}

$repoRoot = (Split-Path -Parent $PSScriptRoot)
Push-Location $repoRoot
try {
    $dockerfilePath = Join-Path (Join-Path $repoRoot "docker") "jellyfin\Dockerfile"
    $composeFilePath = Join-Path $repoRoot $ComposeFile
    $versionFilePath = Join-Path $repoRoot $VersionFile

    $currentVersion = $null
    if (Test-Path $versionFilePath) {
        $currentVersion = (Get-Content -Path $versionFilePath -TotalCount 1).Trim()
        if (-not $currentVersion) {
            throw "Version file is empty: $versionFilePath"
        }
        Write-Step "Loaded current dev version from ${VersionFile}: $currentVersion"
    }
    else {
        $currentVersion = Get-VersionFromDockerfile -DockerfilePath $dockerfilePath
        Write-Step "Version file not found. Using Dockerfile ARG VERSION as base: $currentVersion"
    }

    $nextVersion = Increment-Version -VersionText $currentVersion
    Write-Step "Next dev version: $nextVersion"

    $testProjectPath = Join-Path $repoRoot "Jellyfin.Plugin.TvHeadendApi.Tests\Jellyfin.Plugin.TvHeadendApi.Tests.csproj"

    if ($DryRun) {
        Write-Host "[DRY-RUN] Would run: dotnet test $testProjectPath -c Release --filter `"Category!=LiveIntegration`""
        Write-Host "[DRY-RUN] Would run: docker compose -f $ComposeFile build --build-arg VERSION=$nextVersion $ComposeService"
        Write-Host "[DRY-RUN] Would run: docker compose -f $ComposeFile up -d --force-recreate $ComposeService"
        if (-not $NoLogs) {
            Write-Host "[DRY-RUN] Would run: docker compose -f $ComposeFile logs --no-color --tail=120 $ComposeService"
        }
        Write-Host "[DRY-RUN] Would write version file: $VersionFile -> $nextVersion"
        exit 0
    }

    if (-not (Test-Path $testProjectPath)) {
        throw "Test project not found: $testProjectPath"
    }

    Write-Step "Running unit tests"
    dotnet test $testProjectPath -c Release --filter "Category!=LiveIntegration"
    if ($LASTEXITCODE -ne 0) {
        throw "dotnet test failed with exit code $LASTEXITCODE"
    }

    Write-Step "Building image with VERSION=$nextVersion"
    docker compose -f $ComposeFile build --build-arg "VERSION=$nextVersion" $ComposeService
    if ($LASTEXITCODE -ne 0) {
        throw "docker compose build failed with exit code $LASTEXITCODE"
    }

    Write-Step "Recreating service '$ComposeService'"
    docker compose -f $ComposeFile up -d --force-recreate $ComposeService
    if ($LASTEXITCODE -ne 0) {
        throw "docker compose up failed with exit code $LASTEXITCODE"
    }

    if (-not $NoLogs) {
        Write-Step "Recent logs"
        docker compose -f $ComposeFile logs --no-color --tail=120 $ComposeService
    }

    New-Item -ItemType Directory -Path (Split-Path -Parent $versionFilePath) -Force | Out-Null
    Set-Content -Path $versionFilePath -Value $nextVersion -NoNewline

    Write-Host ""
    Write-Host "Done. Dev version bumped to: $nextVersion" -ForegroundColor Green
    Write-Host "Next run starts from this value in: ${VersionFile}"
}
finally {
    Pop-Location
}

